def opp(oid, name, problem, workflow, behavior, insufficient, value, surfaces, risk, deps, effort, safety, kind, recommendation, coverage, friction_ids, horizon):
    return {"id": oid, "name": name, "problem_solved": problem, "user_workflow": workflow, "proposed_behavior": behavior,
            "why_current_insufficient": insufficient, "expected_product_value": value, "implementation_surfaces": surfaces,
            "semantic_scientific_risk": risk, "dependencies": deps, "rough_effort": effort, "safety_class": safety,
            "classification": kind, "recommendation": recommendation, "github_coverage": coverage, "friction": friction_ids, "roadmap": horizon}


